package com.deskbot.os.service

import android.service.notification.NotificationListenerService
import android.service.notification.StatusBarNotification
import android.util.Log
import com.deskbot.os.MqttManager

class DeskBotNotificationListener : NotificationListenerService() {

    private var mqttManager: MqttManager? = null
    private var lastForwardedTimestamp = 0L
    private val debounceIntervalMs = 3000L // Prevent notification spamming

    override fun onCreate() {
        super.onCreate()
        mqttManager = MqttManager(applicationContext).apply { connect() }
    }

    override fun onNotificationPosted(sbn: StatusBarNotification?) {
        sbn ?: return

        val packageName = sbn.packageName ?: return
        val extras = sbn.notification.extras ?: return

        val title = extras.getString("android.title") ?: ""
        val text = extras.getCharSequence("android.text")?.toString() ?: ""

        // Debounce filter to protect ESP8266 buffer
        val now = System.currentTimeMillis()
        if (now - lastForwardedTimestamp < debounceIntervalMs) return

        // 1. WhatsApp Group / Chat Filtering
        if (packageName == "com.whatsapp" || packageName == "com.whatsapp.w4b") {
            if (title.isNotBlank() && text.isNotBlank()) {
                Log.d("DeskBot_Notif", "WhatsApp Alert -> Title: $title | Text: $text")
                forwardAlert(source = "WhatsApp", sender = title, message = text)
                lastForwardedTimestamp = now
            }
        }
        // 2. Instagram Direct / Mentions
        else if (packageName == "com.instagram.android") {
            if (title.isNotBlank()) {
                Log.d("DeskBot_Notif", "Instagram Alert -> Title: $title | Text: $text")
                forwardAlert(source = "Instagram", sender = title, message = text)
                lastForwardedTimestamp = now
            }
        }
    }

    private fun forwardAlert(source: String, sender: String, message: String) {
        // Format clean payload for ESP8266 OLED
        val cleanSender = sender.take(18)
        val cleanMsg = message.take(30)
        val payload = "{\"source\":\"$source\",\"sender\":\"$cleanSender\",\"msg\":\"$cleanMsg\"}"

        mqttManager?.publishNotification(payload)
    }

    override fun onNotificationRemoved(sbn: StatusBarNotification?) {}
}
